-- Vyapar parity Phase 5 follow-up: §194A TDS on loan interest (lender type and PAN on loans, TDS on loan payments) and
-- the bank branch from the IFSC lookup. Additive, all defaulted. Generated by drizzle-kit; the checks below added by hand.
ALTER TABLE "payment_accounts" ADD COLUMN "branch" text DEFAULT '' NOT NULL;--> statement-breakpoint
ALTER TABLE "loan_payments" ADD COLUMN "tds_amount" numeric(14, 2) DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "loan_payments" ADD COLUMN "tds_base" numeric(14, 2) DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "loan_payments" ADD COLUMN "tds_rate" numeric(14, 2) DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "loans" ADD COLUMN "lender_type" text DEFAULT 'bank' NOT NULL;--> statement-breakpoint
ALTER TABLE "loans" ADD COLUMN "lender_pan" text DEFAULT '' NOT NULL;--> statement-breakpoint
ALTER TABLE "loans" ADD COLUMN "lender_party_id" uuid;--> statement-breakpoint
ALTER TABLE "loans" ADD COLUMN "tds_exempt" boolean DEFAULT false NOT NULL;
--> statement-breakpoint
ALTER TABLE "loans" ADD CONSTRAINT "loans_lender_type" CHECK ("lender_type" IN ('bank', 'nbfc', 'company', 'individual', 'other'));
--> statement-breakpoint
-- TDS is kept from the interest, never more than it.
ALTER TABLE "loan_payments" ADD CONSTRAINT "loan_payments_tds" CHECK ("tds_amount" >= 0 AND "tds_amount" <= "interest" + "tds_base");
